existing required-course classification retained.", "position": 6}, {"level": 100, "semester": 1, "code": "PHY 107", "title": "General Practical Physics I", "units": 1, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 7}, {"level": 100, "semester": 1, "code": "PHY 103", "title": "General Physics III (Behaviour of Matters)", "units": 2, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 8}, {"level": 100, "semester": 1, "code": "PHY 101", "title": "General Physics I", "units": 2, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 9}, {"level": 100, "semester": 1, "code": "MTH 103", "title": "Elementary Mathematics III", "units": 2, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 10}, {"level": 100, "semester": 1, "code": "AUE-GST 100", "title": "Students Life Seminar", "units": 0, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 11}, {"level": 100, "semester": 1, "code": "GET 101", "title": "Engineer in Society", "units": 1, "status": "R", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Registration report does not specify requirement category or contact hours; existing required-course classification retained.", "position": 12}]$data$::jsonb) as r(level int,semester int,code text,title text,units int,status text,lecture_hours int,practical_hours int,elective_group text,note text,position int);
create temp table mechanical_scope on commit drop as
select d.id department_id,d.university_id,l.id level_id,l.sort_order level,s.id semester_id,s.sort_order semester
from public.departments d join public.universities u on u.id=d.university_id
join public.levels l on l.university_id=u.id and l.active and l.sort_order in(100)
join public.academic_periods ap on ap.university_id=u.id and ap.label='2026/2027' and ap.active
join public.semesters s on s.academic_period_id=ap.id and s.active and s.sort_order in(1)
where d.name='Mechanical Engineering' and d.active and u.slug='adeleke-university-ede-osun-state';
create temp table mechanical_other on commit drop as select o.* from public.course_offerings o where not exists(select 1 from mechanical_scope s where s.department_id=o.department_id and s.level_id=o.level_id and s.semester_id=o.semester_id);
create temp table mechanical_existing on commit drop as select o.id,o.course_id,o.department_id,o.level_id,o.semester_id from public.course_offerings o join mechanical_scope s using(department_id,level_id,semester_id);
create temp table mechanical_enrollments on commit drop as select * from public.enrollments;
do $$ begin
if (select count(*) from mechanical_scope)<>1 or (select count(*) from mechanical_requested)<>12 then raise exception 'Mechanical source/scope mismatch'; end if;
end $$;
-- Correct the provisional code in place so existing course/offering IDs stay intact.
do $$ begin
if exists(select 1 from public.courses where code='AUE-MEE 101' and title like '%pending confirmation%') then
 if exists(select 1 from public.courses where code='MEE 101') then raise exception 'Mechanical alias collision requires review'; end if;
 update public.courses set code='MEE 101',title='Introduction to Mechanical Engineering' where code='AUE-MEE 101' and title like '%pending confirmation%';
end if;
end $$;
insert into public.courses(code,title) select distinct code,title from mechanical_requested on conflict(code) do nothing;
insert into public.curriculum_courses(university_id,department_id,level_id,semester_number,course_id,unit_count,requirement_status,position,source_reference,lecture_hours,practical_hours,elective_group,source_code,source_title)
select s.university_id,s.department_id,s.level_id,r.semester,c.id,r.units,r.status,r.position,'Owner-supplied ob_report.pdf, Mechanical Engineering, 2026/2027.1. '||coalesce(r.note,''),r.lecture_hours,r.practical_hours,r.elective_group,r.code,r.title
from mechanical_requested r join mechanical_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(department_id,level_id,semester_number,course_id) do update set unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,position=excluded.position,source_reference=excluded.source_reference,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title,active=true;
insert into public.course_offerings(course_id,university_id,department_id,level_id,semester_id,status,unit_count,requirement_status,lecture_hours,practical_hours,elective_group,source_code,source_title)
select c.id,s.university_id,s.department_id,s.level_id,s.semester_id,'published',r.units,r.status,r.lecture_hours,r.practical_hours,r.elective_group,r.code,r.title
from mechanical_requested r join mechanical_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(course_id,department_id,level_id,semester_id) do update set status='published',unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title;
do $$ begin
if (select count(*) from mechanical_requested r join mechanical_scope s using(level,semester) join public.courses c on c.code=r.code join public.course_offerings o on o.course_id=c.id and o.department_id=s.department_id and o.level_id=s.level_id and o.semester_id=s.semester_id where o.status='published' and o.unit_count=r.units and o.requirement_status=r.status and o.source_title=r.title and o.elective_group is not distinct from r.elective_group and o.lecture_hours is not distinct from r.lecture_hours and o.practical_hours is not distinct from r.practical_hours)<>12 then raise exception 'Mechanical offerings verification failed'; end if;
if (select sum(o.unit_count) from public.course_offerings o join mechanical_scope s using(department_id,level_id,semester_id))<>19 then raise exception 'Mechanical total must be 19 units'; end if;
if exists(select * from mechanical_other except select * from public.course_offerings) then raise exception 'Unrelated offerings changed'; end if;
if exists(select * from mechanical_existing except select id,course_id,department_id,level_id,semester_id from public.course_offerings) then raise exception 'Existing Mechanical IDs changed'; end if;
if exists(select * from mechanical_enrollments except select * from public.enrollments) then raise exception 'Enrollments changed'; end if;
end $$;
